CREATE TABLE records(id TEXT PRIMARY KEY, table_name TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), created_at REAL NOT NULL);
CREATE INDEX records_by_table ON records(table_name, created_at, id);
CREATE TABLE transaction_state(id INTEGER PRIMARY KEY CHECK(id=1), revision INTEGER NOT NULL DEFAULT 0, token TEXT NOT NULL DEFAULT '');
INSERT INTO transaction_state(id) VALUES(1);
CREATE TABLE transaction_assertion(id INTEGER PRIMARY KEY CHECK(id=1), valid INTEGER NOT NULL CHECK(valid=1));
CREATE TABLE job_outbox(id TEXT PRIMARY KEY, operation TEXT NOT NULL, args TEXT NOT NULL CHECK(json_valid(args)), due_at INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', lease_until INTEGER NOT NULL DEFAULT 0, lease_token TEXT NOT NULL DEFAULT '', attempts INTEGER NOT NULL DEFAULT 0, completed_at INTEGER);
CREATE INDEX jobs_due ON job_outbox(status, due_at, lease_until);
